import {BUNKER_W,BUNKER_H,bunkerStatus} from './campaign.js';
import {TW,TH,DEPOSITS} from './render.js';
import {BUILD} from './engine.js';
const palette={home:'#efbf78',storage:'#d9c777',generator:'#ffcf65',water:'#74d9ef',farm:'#9ee58a',lab:'#c0a4e5',workshop:'#e2aa7d',med:'#ef9aaf',mine:'#b9a5df',smelter:'#ed9669',stairs:'#b1babc'};
export function campaignLayout(c,width,height){let minX=Math.min(...c.bunkers.map(b=>b.gx)),maxX=Math.max(...c.bunkers.map(b=>b.gx)),minY=Math.min(...c.bunkers.map(b=>b.gy)),maxY=Math.max(...c.bunkers.map(b=>b.gy));let cols=maxX-minX+1,rows=maxY-minY+1,gap=width<400?10:28,pad=width<400?8:30,scale=Math.max(.001,Math.min((width-pad*2-gap*(cols-1))/(cols*30*TW),(height-pad*2-gap*(rows-1)-rows*(width<400?10:25))/(rows*20*TH)));let w=30*TW*scale,h=20*TH*scale;return c.bunkers.map(b=>({id:b.id,x:pad+(b.gx-minX)*(w+gap),y:pad+(b.gy-minY)*(h+gap+(width<400?10:25)),w,h,scale}));}
export function campaignHit(c,x,y,width,height){return campaignLayout(c,width,height).find(r=>x>=r.x&&x<r.x+r.w&&y>=r.y&&y<r.y+r.h)?.id??null;}
export function drawCampaignOverview(g,c,width,height,mini=false){g.clearRect(0,0,width,height);g.fillStyle=mini?'#0c2330aa':'#0a1720';g.fillRect(0,0,width,height);let layout=campaignLayout(c,width,height);for(let l of c.links){let a=layout.find(r=>r.id===l.a),b=layout.find(r=>r.id===l.b);g.strokeStyle='#75baa8aa';g.lineWidth=mini?1:4;g.beginPath();g.moveTo(a.x+a.w/2,a.y+a.h/2);g.lineTo(b.x+b.w/2,b.y+b.h/2);g.stroke();}for(let r of layout){let b=c.bunkers.find(b=>b.id===r.id),s=b.world;g.fillStyle=b.founded?'#253c48':'#172a36';g.fillRect(r.x,r.y,r.w,r.h);let sx=r.w/30,sy=r.h/20;for(let n of s.cells){if(n.x>=30||n.y>=20||!n.seen&&n.type!=='open')continue;g.fillStyle=n.type==='open'?(palette[n.building]||'#6b8998'):DEPOSITS[n.feature]?.color||'#425867';g.fillRect(r.x+n.x*sx,r.y+n.y*sy,Math.max(.7,sx-.3),Math.max(.7,sy-.3));}for(let p of s.people){if(p.health<=0)continue;if(!mini&&p.path.length){g.strokeStyle='#a0edd577';g.lineWidth=1;g.beginPath();g.moveTo(r.x+(p.x+.5)*sx,r.y+(p.y+.7)*sy);for(let n of p.path)g.lineTo(r.x+(n.x+.5)*sx,r.y+(n.y+.7)*sy);g.stroke();}g.fillStyle=p.task==='Отдых'?'#b8b6ff':'#a9ffe7';g.beginPath();g.arc(r.x+(p.x+.5)*sx,r.y+(p.y+.7)*sy,mini?1.4:3,0,7);g.fill();}g.strokeStyle=b.id===c.active?'#ffe0a0':b.automatic?'#82d5aa':'#7696a5';g.lineWidth=b.id===c.active?2:1;g.strokeRect(r.x,r.y,r.w,r.h);g.font=(mini?'8':'12')+'px system-ui';g.fillStyle='#e5eadd';g.textAlign='left';g.fillText(b.name+(mini?'':' · '+bunkerStatus(b).state),r.x,r.y+r.h+(mini?9:17),r.w);}for(let t of c.shipments){let a=layout.find(r=>r.id===t.from),b=layout.find(r=>r.id===t.to),f=1-t.remaining/t.total;if(!a||!b)continue;let x=a.x+a.w/2+(b.x+b.w/2-a.x-a.w/2)*f,y=a.y+a.h/2+(b.y+b.h/2-a.y-a.h/2)*f;g.fillStyle=t.kind==='found'?'#e5bdff':'#ffdf84';g.beginPath();g.arc(x,y,mini?2:5,0,7);g.fill();}}
